1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.repository.OwnerRepository;
12	
13	/**
14	 * Assigns a newly created owner a {@code customerCode} formatted {@code '<REGION>-<HASH8>'}:
15	 * REGION is the region code derived from the owner's postcode (NSW 2000-2099, VIC 3000-3099,
16	 * QLD 4000-4099, otherwise {@code UNKNOWN}), and HASH8 is the first eight UPPER-case hex
17	 * characters of the SHA-256 digest over the normalized (E.164) telephone concatenated with the
18	 * owner's last name. The former per-city sequence number is gone, so the code no longer depends
19	 * on how many owners already exist. Mutates the {@link Owner} in place so it is persisted and
20	 * returned with the code, and so every value derived from the customerCode (membership number,
21	 * check digit, audit line and locality) reflects the new region-and-hash identity.
22	 *
23	 * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
24	 * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
25	 * makes it unique, so distinct owners always receive distinct customerCodes.
26	 */
27	public class AssignOwnerCustomerCode {
28	
29	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
30	        String region = PostcodeRegions.regionForPostcode(owner.getPostcode());
31	        if (region == null) {
32	            region = "UNKNOWN";
33	        }
34	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
35	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
36	        String base = region + "-" + hash8(telephone + lastName);
37	        owner.setCustomerCode(deduplicate(base, owner, ownerRepository));
38	    }
39	
40	    /**
41	     * Return {@code base} if no existing owner already holds it, otherwise
42	     * {@code base + "-" + n} with the smallest {@code n >= 2} that is unused.
43	     */
44	    private static String deduplicate(String base, Owner owner, OwnerRepository ownerRepository) {
45	        Set<String> taken = new HashSet<>();
46	        for (Owner existing : ownerRepository.findAll()) {
47	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
48	                continue; // never collide with the owner itself
49	            }
50	            if (existing.getCustomerCode() != null) {
51	                taken.add(existing.getCustomerCode());
52	            }
53	        }
54	        if (!taken.contains(base)) {
55	            return base;
56	        }
57	        int n = 2;
58	        while (taken.contains(base + "-" + n)) {
59	            n++;
60	        }
61	        return base + "-" + n;
62	    }
63	
64	    /** First eight UPPER-case hex characters (four bytes) of SHA-256 over the UTF-8 bytes. */
65	    private static String hash8(String value) {
66	        try {
67	            byte[] digest = MessageDigest.getInstance("SHA-256")
68	                    .digest(value.getBytes(StandardCharsets.UTF_8));
69	            StringBuilder sb = new StringBuilder(8);
70	            for (int i = 0; i < 4; i++) {
71	                sb.append(String.format("%02X", digest[i]));
72	            }
73	            return sb.toString();
74	        }
75	        catch (NoSuchAlgorithmException ex) {
76	            throw new IllegalStateException("SHA-256 not available", ex);
77	        }
78	    }
79	}
