1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives the single {@code identityKey} used for all owner duplicate detection.
12	 *
13	 * <p>The key is the lower-case SHA-256 hex digest of {@code normalizedTelephone + '|' +
14	 * lowerEmail + '|' + soundex(lastName)}. A create is a duplicate only when a new owner's
15	 * WHOLE identityKey equals an existing owner's — the former separate telephone, email and
16	 * household checks are now expressed through this one hashed key. Because the telephone is
17	 * part of the key, two owners with the same last name and postcode but different
18	 * telephones have different keys and are both allowed; only an exact full-key match is a
19	 * duplicate (they may still be flagged a soft possible duplicate — see
20	 * {@link AssignOwnerPossibleDuplicate}).
21	 *
22	 * <p>Both sides are canonicalized the same way so a new owner and the stored owners
23	 * compare on equal footing: telephone via {@link E164Telephone}, email trimmed and
24	 * lower-cased, and the last name folded to its {@link Soundex} code (empty when absent).
25	 */
26	public final class OwnerIdentity {
27	
28	    private OwnerIdentity() {
29	    }
30	
31	    /** The owner's derived identity key: a 64-character lower-case SHA-256 hex digest. */
32	    public static String identityKey(Owner owner) {
33	        String raw = telephone(owner) + "|" + email(owner) + "|" + Soundex.encode(owner.getLastName());
34	        return sha256hex(raw);
35	    }
36	
37	    private static String telephone(Owner owner) {
38	        String e164 = E164Telephone.toE164OrNull(owner.getTelephone());
39	        if (e164 != null) {
40	            return e164;
41	        }
42	        return owner.getTelephone() == null ? "" : owner.getTelephone();
43	    }
44	
45	    private static String email(Owner owner) {
46	        String value = owner.getEmail();
47	        if (value == null) {
48	            return "";
49	        }
50	        String trimmed = value.trim();
51	        return trimmed.isEmpty() ? "" : trimmed.toLowerCase(Locale.ROOT);
52	    }
53	
54	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code raw}. */
55	    private static String sha256hex(String raw) {
56	        try {
57	            byte[] hash = MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder sb = new StringBuilder(hash.length * 2);
59	            for (byte b : hash) {
60	                sb.append(String.format("%02x", b));
61	            }
62	            return sb.toString();
63	        }
64	        catch (NoSuchAlgorithmException e) {
65	            throw new IllegalStateException("SHA-256 not available", e);
66	        }
67	    }
68	}
