1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	
5	/**
6	 * Fixed city-to-region and region-to-postcode-range tables used to validate an owner's
7	 * postcode against the region derived from the owner's city.
8	 *
9	 * <p>Cities: Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD. A city with no known
10	 * region accepts any 4-digit postcode. Ranges (inclusive): NSW 2000-2099,
11	 * VIC 3000-3099, QLD 4000-4099.
12	 */
13	public final class PostcodeRegions {
14	
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    private static final Map<String, int[]> REGION_RANGE = Map.of(
19	            "NSW", new int[] {2000, 2099},
20	            "VIC", new int[] {3000, 3099},
21	            "QLD", new int[] {4000, 4099});
22	
23	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
24	            "NSW", "Australia/Sydney",
25	            "VIC", "Australia/Melbourne",
26	            "QLD", "Australia/Brisbane");
27	
28	    private PostcodeRegions() {
29	    }
30	
31	    /** IANA timezone name for the region, or null when the region has no known timezone. */
32	    public static String timezoneForRegion(String region) {
33	        return region == null ? null : REGION_TIMEZONE.get(region);
34	    }
35	
36	    /** Canonical region for the city, or null when the city has no known region. */
37	    public static String regionFor(String city) {
38	        return CITY_REGION.get(city);
39	    }
40	
41	    /**
42	     * Canonical region whose inclusive postcode range contains {@code postcode}, or null
43	     * when the postcode is blank, not a number, or in no known range.
44	     */
45	    public static String regionForPostcode(String postcode) {
46	        if (postcode == null || postcode.isBlank()) {
47	            return null;
48	        }
49	        int value;
50	        try {
51	            value = Integer.parseInt(postcode.trim());
52	        }
53	        catch (NumberFormatException ex) {
54	            return null;
55	        }
56	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
57	            int[] range = entry.getValue();
58	            if (value >= range[0] && value <= range[1]) {
59	                return entry.getKey();
60	            }
61	        }
62	        return null;
63	    }
64	
65	    /**
66	     * True when the 4-digit postcode is valid for the city: valid when the city has no
67	     * known region, otherwise valid only when the postcode falls within that region's
68	     * inclusive range.
69	     */
70	    static boolean isValid(String city, int postcode) {
71	        String region = regionFor(city);
72	        if (region == null) {
73	            return true; // city with no known region accepts any 4-digit postcode
74	        }
75	        int[] range = REGION_RANGE.get(region);
76	        return range == null || (postcode >= range[0] && postcode <= range[1]);
77	    }
78	}
79

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	
12	/**
13	 * Emits audit output for a newly created owner via the dedicated {@code AUDIT}
14	 * logger. Runs after {@link SaveOwner} so the persisted owner id is available.
15	 *
16	 * <p>Two things are emitted:
17	 * <ul>
18	 * <li>a human-readable audit line carrying the owner id, the assigned
19	 * {@code customerCode}, the effective {@code registrationDate}, the numeric
20	 * {@code membershipLevel} and the {@code membershipNumber}; and</li>
21	 * <li>an immutable structured event as a JSON object
22	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}},
23	 * where {@code seq} is a process-wide monotonically increasing integer across
24	 * creates.</li>
25	 * </ul>
26	 *
27	 * <p>The structured event carries the owner's <em>current primary
28	 * identifier</em>. Today that identifier is the {@code customerCode}; it is read
29	 * through {@link #primaryIdentifier(Owner)} so that when the customerCode is
30	 * later unified into the memberId, the event automatically carries the memberId
31	 * instead — the JSON key stays {@code customerCode} but its value tracks
32	 * whatever the primary identifier has become.
33	 */
34	public class AuditOwnerCreated {
35	
36	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
37	
38	    /** Process-wide monotonically increasing sequence across all owner creates. */
39	    private static final AtomicLong SEQUENCE = new AtomicLong();
40	
41	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
42	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
43	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
44	                ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
45	
46	        long seq = SEQUENCE.incrementAndGet();
47	        AUDIT.info(event(seq, owner.getId(), primaryIdentifier(owner),
48	                ownerMapper.membershipLevel(owner)));
49	    }
50	
51	    /**
52	     * The owner's current primary identifier. Currently the {@code customerCode};
53	     * when the customerCode is unified into the memberId, this becomes the single
54	     * place to switch, and every emitted event follows.
55	     */
56	    private static String primaryIdentifier(Owner owner) {
57	        return owner.getCustomerCode();
58	    }
59	
60	    /**
61	     * Render the immutable structured event as a JSON object
62	     * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}}.
63	     */
64	    private static String event(long seq, Integer ownerId, String customerCode, Integer membershipLevel) {
65	        return "{"
66	                + "\"seq\":" + seq + ","
67	                + "\"ownerId\":" + ownerId + ","
68	                + "\"customerCode\":" + quote(customerCode) + ","
69	                + "\"membershipLevel\":" + membershipLevel + ","
70	                + "\"event\":\"OWNER_CREATED\""
71	                + "}";
72	    }
73	
74	    /** JSON-encode a string value, or {@code null} literal when absent. */
75	    private static String quote(String value) {
76	        if (value == null) {
77	            return "null";
78	        }
79	        StringBuilder sb = new StringBuilder(value.length() + 2).append('"');
80	        for (int i = 0; i < value.length(); i++) {
81	            char c = value.charAt(i);
82	            switch (c) {
83	                case '"' -> sb.append("\\\"");
84	                case '\\' -> sb.append("\\\\");
85	                case '\n' -> sb.append("\\n");
86	                case '\r' -> sb.append("\\r");
87	                case '\t' -> sb.append("\\t");
88	                default -> {
89	                    if (c < 0x20) {
90	                        sb.append(String.format("\\u%04x", (int) c));
91	                    }
92	                    else {
93	                        sb.append(c);
94	                    }
95	                }
96	            }
97	        }
98	        return sb.append('"').toString();
99	    }
100	}
