1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(\"/api/owners/\" + owner.getId())")
22	    @Mapping(target = "displayName",
23	            expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
24	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
25	    @Mapping(target = "initials", expression = "java(initials(owner))")
26	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
31	    @Mapping(target = "locality", expression = "java(locality(owner))")
32	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
33	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
34	    @Mapping(target = "identityKey",
35	            expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.identityKey(owner))")
36	    @Mapping(target = "bulkSignupWarning",
37	            expression = "java(owner.getBulkSignupWarning() != null && owner.getBulkSignupWarning())")
38	    @Mapping(target = "capacityWarning",
39	            expression = "java(owner.getCapacityWarning() != null && owner.getCapacityWarning())")
40	    @Mapping(target = "possibleDuplicate",
41	            expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    @Mapping(target = "deleted",
43	            expression = "java(owner.getDeleted() != null && owner.getDeleted())")
44	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
45	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
46	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
47	    OwnerDto toOwnerDto(Owner owner);
48	
49	    /** The stored E.164 'telephone' formatted for humans: the country code, a space, then the
50	     *  national digits grouped in threes (e.g. '+61 412 345 678'). The raw 'telephone' stays
51	     *  E.164. Null when the stored value is not a recognised E.164 number. */
52	    default String telephoneDisplay(Owner owner) {
53	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
54	                .toDisplayOrNull(owner.getTelephone());
55	    }
56	
57	    /** Age band derived from birthDate relative to registrationDate: 'MINOR' when under
58	     *  18, 'ADULT' from 18 to 64, 'SENIOR' at 65 or over. Null when either date is absent. */
59	    default String ageBand(Owner owner) {
60	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
64	        if (age < 18) {
65	            return "MINOR";
66	        }
67	        if (age < 65) {
68	            return "ADULT";
69	        }
70	        return "SENIOR";
71	    }
72	
73	    /** 'EMAIL' when the owner has a non-blank email address, otherwise 'PHONE'. */
74	    default String contactPreference(Owner owner) {
75	        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
76	    }
77	
78	    /** The owner's salutation: 'title' + ' ' + lastName when a title is present, else just the
79	     *  lastName. */
80	    default String salutation(Owner owner) {
81	        String title = owner.getTitle();
82	        if (title != null && !title.isBlank()) {
83	            return title + " " + owner.getLastName();
84	        }
85	        return owner.getLastName();
86	    }
87	
88	    /** Upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
89	    default String initials(Owner owner) {
90	        return owner.getFirstName().substring(0, 1).toUpperCase()
91	                + "." + owner.getLastName().substring(0, 1).toUpperCase() + ".";
92	    }
93	
94	    /** Membership number '<customerCode>-M<YY>', YY = last two digits of the
95	     *  fiscal year of the (business-day-adjusted) registrationDate, where the fiscal
96	     *  year starts on 1 July. Null unless both source fields are present. */
97	    default String membershipNumber(Owner owner) {
98	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
99	            return null;
100	        }
101	        return String.format("%s-M%02d", owner.getCustomerCode(),
102	                fiscalYearOf(owner.getRegistrationDate()) % 100);
103	    }
104	
105	    /** The fiscal year of the (business-day-adjusted) registrationDate as 'FY<YY>',
106	     *  where the fiscal year starts on 1 July and is labelled by the calendar year in
107	     *  which it ends (e.g. 2 Jul 2025 -> FY26, 30 Jun 2026 -> FY26). Null when there is
108	     *  no registrationDate. */
109	    default String fiscalYear(Owner owner) {
110	        if (owner.getRegistrationDate() == null) {
111	            return null;
112	        }
113	        return String.format("FY%02d", fiscalYearOf(owner.getRegistrationDate()) % 100);
114	    }
115	
116	    /** The calendar year in which the fiscal year containing {@code date} ends. The fiscal
117	     *  year starts on 1 July, so July-December fall in the fiscal year ending the following
118	     *  calendar year, and January-June in the one ending the current year. */
119	    static int fiscalYearOf(java.time.LocalDate date) {
120	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
121	                ? date.getYear() + 1 : date.getYear();
122	    }
123	
124	    /** A single Luhn check digit (0-9) computed over the digits contained in the
125	     *  owner's customerCode. Null when the customerCode is absent. */
126	    default Integer checkDigit(Owner owner) {
127	        String code = owner.getCustomerCode();
128	        if (code == null) {
129	            return null;
130	        }
131	        int sum = 0;
132	        boolean dbl = true;
133	        for (int i = code.length() - 1; i >= 0; i--) {
134	            char c = code.charAt(i);
135	            if (c < '0' || c > '9') {
136	                continue;
137	            }
138	            int d = c - '0';
139	            if (dbl) {
140	                d *= 2;
141	                if (d > 9) {
142	                    d -= 9;
143	                }
144	            }
145	            sum += d;
146	            dbl = !dbl;
147	        }
148	        return (10 - (sum % 10)) % 10;
149	    }
150	
151	    /** Membership points: starts at 0, adds 2 when an email is present, adds 1 when
152	     *  namesakeCount is 0, adds 2 for a household of 3 or more, and adds 3 for tenure
153	     *  (at least one elapsed fiscal year between the registrationDate and today, the
154	     *  fiscal year starting 1 July). */
155	    default Integer membershipPoints(Owner owner) {
156	        int points = 0;
157	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
158	        if (hasEmail) {
159	            points += 2;
160	        }
161	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
162	            points += 1;
163	        }
164	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
165	            points += 2;
166	        }
167	        if (owner.getRegistrationDate() != null
168	                && fiscalYearOf(java.time.LocalDate.now())
169	                        - fiscalYearOf(owner.getRegistrationDate()) >= 1) {
170	            points += 3;
171	        }
172	        return points;
173	    }
174	
175	    /** Numeric membership level from 1 to 4, mapped from membershipPoints: level 1 for
176	     *  0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. Clamped to the owner's
177	     *  {@code membershipLevelCap} when present, so a new owner's level cannot exceed one
178	     *  above the maximum among their household members at creation. */
179	    default Integer membershipLevel(Owner owner) {
180	        int level = uncappedMembershipLevel(owner);
181	        Integer cap = owner.getMembershipLevelCap();
182	        if (cap != null && level > cap) {
183	            return cap;
184	        }
185	        return level;
186	    }
187	
188	    /** The membership level derived purely from membershipPoints, before any
189	     *  household-derived ceiling is applied. */
190	    default Integer uncappedMembershipLevel(Owner owner) {
191	        int points = membershipPoints(owner);
192	        if (points <= 1) {
193	            return 1;
194	        }
195	        if (points <= 3) {
196	            return 2;
197	        }
198	        if (points <= 5) {
199	            return 3;
200	        }
201	        return 4;
202	    }
203	
204	    /** The owner's locality: the REGION component of the customerCode ('<REGION>-<HASH8>'),
205	     *  which is derived from the postcode at creation. 'UNKNOWN' when the customerCode is absent
206	     *  or carries no region prefix. Derived from the region-and-hash identity so it always agrees
207	     *  with the code, membership number and check digit. */
208	    default String locality(Owner owner) {
209	        String code = owner.getCustomerCode();
210	        if (code == null) {
211	            return "UNKNOWN";
212	        }
213	        int dash = code.indexOf('-');
214	        return dash <= 0 ? "UNKNOWN" : code.substring(0, dash);
215	    }
216	
217	    /** The owner's segment, formatted '<TIER>_<AREA>': TIER is 'PREMIUM' when
218	     *  membershipLevel is 3 or more, otherwise 'STANDARD'; AREA is 'METRO' when the
219	     *  locality is a known region (NSW, VIC or QLD), otherwise 'REGIONAL'. */
220	    default String ownerSegment(Owner owner) {
221	        Integer level = membershipLevel(owner);
222	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
223	        String area = org.springframework.samples.petclinic.rest.function.owner.PostcodeRegions
224	                .timezoneForRegion(locality(owner)) != null ? "METRO" : "REGIONAL";
225	        return tier + "_" + area;
226	    }
227	
228	    /** The IANA timezone name derived from the owner's locality/region using the fixed
229	     *  region-to-timezone table (NSW->Australia/Sydney, VIC->Australia/Melbourne,
230	     *  QLD->Australia/Brisbane). Null when the locality is not a region in the table. */
231	    default String timezone(Owner owner) {
232	        return org.springframework.samples.petclinic.rest.function.owner.PostcodeRegions
233	                .timezoneForRegion(locality(owner));
234	    }
235	
236	    Owner toOwner(OwnerDto ownerDto);
237	
238	    @Mapping(target = "id", ignore = true)
239	    @Mapping(target = "pets", ignore = true)
240	    Owner toOwner(OwnerFieldsDto ownerDto);
241	
242	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
243	
244	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
245	
246	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
247	        OwnerPageDto ownerPageDto = new OwnerPageDto();
248	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
249	        ownerPageDto.setPage(ownerPage.getNumber());
250	        ownerPageDto.setSize(ownerPage.getSize());
251	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
252	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
253	        return ownerPageDto;
254	    }
255	}
