3	/**
4	 * American Soundex encoder used to fold a last name to its phonetic key. The key is the
5	 * first letter followed by three digits (zero-padded, truncated to four characters), with
6	 * the usual coding rules: adjacent letters sharing a code collapse to one, {@code H} and
7	 * {@code W} are transparent (letters either side are treated as adjacent), and the vowels
8	 * {@code A E I O U Y} act as separators that let an otherwise-repeated code count twice.
9	 *
10	 * <p>Used both in the owner {@code identityKey} (see {@link OwnerIdentity}) and in the
11	 * soft possible-duplicate match (see {@link AssignOwnerPossibleDuplicate}) so both key off
12	 * the same phonetic surname.
13	 */
14	public final class Soundex {
15	
16	    private Soundex() {
17	    }
18	
19	    /** The Soundex code of {@code value}, or {@code ""} when it has no letters (or is null). */
20	    public static String encode(String value) {
21	        if (value == null) {
22	            return "";
23	        }
24	        StringBuilder letters = new StringBuilder();
25	        for (int i = 0; i < value.length(); i++) {
26	            char c = value.charAt(i);
27	            if (Character.isLetter(c)) {
28	                letters.append(Character.toUpperCase(c));
29	            }
30	        }
31	        if (letters.length() == 0) {
32	            return "";
33	        }
34	        StringBuilder code = new StringBuilder();
35	        char first = letters.charAt(0);
36	        code.append(first);
37	        char prev = codeOf(first);
38	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
39	            char c = letters.charAt(i);
40	            if (c == 'H' || c == 'W') {
41	                continue; // transparent: does not change the previous code
42	            }
43	            char d = codeOf(c);
44	            if (d != '0' && d != prev) {
45	                code.append(d);
46	            }
47	            prev = d; // vowels (code '0') reset, so a later matching code counts again
48	        }
49	        while (code.length() < 4) {
50	            code.append('0');
51	        }
52	        return code.toString();
53	    }
54	
55	    /** Soundex digit for an upper-case letter; {@code '0'} for A E I O U Y (and H, W). */
56	    private static char codeOf(char c) {
57	        switch (c) {
58	            case 'B': case 'F': case 'P': case 'V':
59	                return '1';
60	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
61	                return '2';
62	            case 'D': case 'T':
63	                return '3';
64	            case 'L':
65	                return '4';
66	            case 'M': case 'N':
67	                return '5';
68	            case 'R':
69	                return '6';
70	            default:
71	                return '0';
72	        }
73	    }
74	}
