1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Converts a raw telephone string to canonical E.164 form.
8	 *
9	 * <p>Rules:
10	 * <ul>
11	 *   <li>strip spaces, dashes and brackets;</li>
12	 *   <li>keep a leading {@code '+'} and country code when present;</li>
13	 *   <li>otherwise assume country code {@code '+61'} and drop a single leading {@code '0'}
14	 *       from the national digits;</li>
15	 *   <li>when the number carries an explicit country code, its national-number length must match
16	 *       that country: {@code '+61'} requires 9 national digits and {@code '+1'} requires 10;
17	 *       country codes outside this table fall back to the generic bound below;</li>
18	 *   <li>require 8 to 15 digits after the {@code '+'}.</li>
19	 * </ul>
20	 *
21	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
22	 * becomes {@code "+6421123456"}. A value that cannot form valid E.164 has no canonical form.
23	 */
24	public final class E164Telephone {
25	
26	    /**
27	     * Required national-number digit count for each supported country code, longest code first so a
28	     * {@code "61…"} number is matched as {@code +61} rather than as some shorter code. Country codes
29	     * absent here are validated only by the generic 8-to-15 total-digit bound.
30	     */
31	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = new LinkedHashMap<>();
32	
33	    static {
34	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("61", 9); // Australia
35	        NATIONAL_LENGTH_BY_COUNTRY_CODE.put("1", 10); // North American Numbering Plan
36	    }
37	
38	    private E164Telephone() {
39	    }
40	
41	    /**
42	     * @return the E.164 form of {@code raw}, or {@code null} if it cannot form a valid E.164 number.
43	     */
44	    public static String toE164OrNull(String raw) {
45	        if (raw == null) {
46	            return null;
47	        }
48	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
49	        String digits;
50	        if (cleaned.startsWith("+")) {
51	            digits = cleaned.substring(1);
52	            // An explicit country code fixes the expected national-number length.
53	            if (!nationalLengthMatchesCountry(digits)) {
54	                return null;
55	            }
56	        } else {
57	            if (cleaned.startsWith("0")) {
58	                cleaned = cleaned.substring(1); // drop a single leading national-trunk '0'
59	            }
60	            digits = "61" + cleaned;
61	        }
62	        if (!digits.matches("[0-9]{8,15}")) {
63	            return null;
64	        }
65	        return "+" + digits;
66	    }
67	
68	    /**
69	     * Formats a stored E.164 number for humans: the country code, a space, then the national digits
70	     * grouped in threes (left to right), e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}.
71	     * The raw E.164 value is left untouched; this is a presentation-only rendering.
72	     *
73	     * @return the human-readable rendering of {@code e164}, or {@code null} when {@code e164} is not a
74	     *   value this normalizer produces — no leading {@code '+'}, not 8 to 15 digits, or a country code
75	     *   outside {@link #NATIONAL_LENGTH_BY_COUNTRY_CODE} whose national-number split is unknown.
76	     */
77	    public static String toDisplayOrNull(String e164) {
78	        if (e164 == null) {
79	            return null;
80	        }
81	        String cleaned = e164.replaceAll("[\\s()\\-]", "");
82	        if (!cleaned.startsWith("+")) {
83	            return null;
84	        }
85	        String digits = cleaned.substring(1);
86	        if (!digits.matches("[0-9]{8,15}")) {
87	            return null;
88	        }
89	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
90	            String countryCode = entry.getKey();
91	            if (digits.startsWith(countryCode) && digits.length() - countryCode.length() == entry.getValue()) {
92	                String national = digits.substring(countryCode.length());
93	                return "+" + countryCode + " " + groupInThrees(national);
94	            }
95	        }
96	        return null;
97	    }
98	
99	    /** Groups a run of digits into space-separated chunks of three, left to right. */
100	    private static String groupInThrees(String national) {
101	        StringBuilder sb = new StringBuilder();
102	        for (int i = 0; i < national.length(); i++) {
103	            if (i > 0 && i % 3 == 0) {
104	                sb.append(' ');
105	            }
106	            sb.append(national.charAt(i));
107	        }
108	        return sb.toString();
109	    }
110	
111	    /**
112	     * Checks the national-number length of an explicitly country-coded number against its country.
113	     *
114	     * @param digits the digits following the {@code '+'} (country code plus national number).
115	     * @return {@code false} only when {@code digits} begins with a supported country code and the
116	     *   remaining national digits are not the exact length that country requires; {@code true} for
117	     *   any country code outside the table (left to the generic length bound).
118	     */
119	    private static boolean nationalLengthMatchesCountry(String digits) {
120	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
121	            String countryCode = entry.getKey();
122	            if (digits.startsWith(countryCode)) {
123	                return digits.length() - countryCode.length() == entry.getValue();
124	            }
125	        }
126	        return true;
127	    }
128	}
