1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Normalizes a new owner's telephone to E.164 form: strips spaces, dashes and brackets, keeps a
9	 * leading '+' and country code when present, otherwise assumes country code '+61' and drops a
10	 * single leading '0' from the national digits, and requires 8 to 15 digits after the '+'. When a
11	 * country code is given explicitly its national-number length must match that country ('+61' needs
12	 * 9 national digits, '+1' needs 10). So '0412 345 678' is stored as '+61412345678'. The stored (and
13	 * later returned) value is the E.164 string; anything that cannot form valid E.164 is a 400. Mutates
14	 * the built {@link Owner} in place
15	 * so {@link SaveOwner} persists the normalized value.
16	 */
17	public class NormalizeOwnerTelephone {
18	
19	    public void service(@Val Owner owner) throws InvalidTelephoneException {
20	        String e164 = E164Telephone.toE164OrNull(owner.getTelephone());
21	        if (e164 == null) {
22	            throw new InvalidTelephoneException(
23	                    "Telephone must form a valid E.164 number with 8 to 15 digits after the '+', "
24	                            + "and a national-number length matching its country code "
25	                            + "('+61' requires 9 national digits, '+1' requires 10)");
26	        }
27	        owner.setTelephone(e164);
28	    }
29	}
