1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (non-hard) duplicate. Runs after {@link RejectDuplicateOwnerIdentity} has
10	 * already rejected exact {@code identityKey} matches (409), so any owner reaching this step
11	 * is <em>not</em> a hard duplicate. When the new owner's {@code identityKey} nonetheless
12	 * differs from an existing owner's while their {@code soundex(lastName)} and {@code postcode}
13	 * both match, the create still proceeds and the new owner is marked as a possible duplicate:
14	 * its {@code possibleDuplicateOf} is set to the matching owner's id (the earliest such owner
15	 * when several match). This is exactly the household-look-alike case that is no longer a hard
16	 * duplicate: same phonetic surname and postcode but a different telephone (or email) yields a
17	 * different key, so it is admitted and flagged rather than rejected. Mutates the {@link Owner}
18	 * in place so the value is persisted by {@link SaveOwner} and surfaces as
19	 * {@code possibleDuplicate}/{@code possibleDuplicateOf} on the response.
20	 *
21	 * <p>A <em>declared</em> household member — one carrying {@code sharesHousehold} — is
22	 * deliberately never flagged: it shares the household by design, so it is not a suspected
23	 * duplicate.
24	 *
25	 * <p>No-ops (leaving {@code possibleDuplicateOf} null, so {@code possibleDuplicate} is
26	 * false) when the owner declared a shared household, has no last name or postcode, or no
27	 * matching existing owner exists.
28	 */
29	public class AssignOwnerPossibleDuplicate {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
32	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return; // a declared household member is not a suspected duplicate
34	        }
35	        String postcode = owner.getPostcode();
36	        if (owner.getLastName() == null || postcode == null || postcode.isBlank()) {
37	            return; // nothing to match on
38	        }
39	        String soundex = Soundex.encode(owner.getLastName());
40	        String identityKey = OwnerIdentity.identityKey(owner);
41	        Owner match = null;
42	        for (Owner existing : ownerRepository.findAll()) {
43	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
44	                continue; // never match the owner against itself
45	            }
46	            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
47	                continue; // an identical key is a hard, not a possible, duplicate
48	            }
49	            if (!soundex.equals(Soundex.encode(existing.getLastName()))) {
50	                continue;
51	            }
52	            if (!postcode.equals(existing.getPostcode())) {
53	                continue;
54	            }
55	            if (match == null || existing.getId() < match.getId()) {
56	                match = existing; // earliest matching owner
57	            }
58	        }
59	        if (match != null) {
60	            owner.setPossibleDuplicateOf(match.getId());
61	        }
62	    }
63	}
