11	/**
12	 * Assigns the new owner a deterministic {@code householdId} derived purely from its
13	 * {@code lastName} and {@code postcode}: the first twelve UPPER-case hex characters of
14	 * SHA-256 over {@code normalizedLastName + '|' + postcode}. Because the id is a pure
15	 * function of those two fields, every owner with the same (normalized) last name and
16	 * postcode resolves to the same {@code householdId} automatically — they are, by
17	 * definition, the same household — regardless of registration order and independent of
18	 * the {@code sharesHousehold} create flag.
19	 *
20	 * <p>The flag no longer creates the household link; it only lets a second member of an
21	 * already-existing household bypass the duplicate block (see
22	 * {@link RejectDuplicateOwnerIdentity}). Everything that keys off the household —
23	 * duplicate detection and the household-size snapshot feeding the membership level —
24	 * reads this computed value.
25	 *
26	 * <p>No-ops (leaving {@code householdId} null, so the owner is a household of one) when
27	 * the owner has no last name or no postcode: without a postcode there is nothing to key
28	 * a household on.
29	 */
30	public class AssignOwnerHousehold {
31	
32	    public void service(@Val Owner owner) {
33	        String lastName = normalize(owner.getLastName());
34	        String postcode = owner.getPostcode();
35	        if (lastName == null || postcode == null || postcode.isBlank()) {
36	            return; // no household without both a last name and a postcode
37	        }
38	        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
39	    }
40	
41	    /** First twelve UPPER-case hex characters of SHA-256 over {@code lastName + '|' + postcode}. */
42	    private static String deriveHouseholdId(String lastName, String postcode) {
43	        try {
44	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
45	            byte[] hash = digest.digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
46	            StringBuilder sb = new StringBuilder(12);
47	            for (int i = 0; i < 6; i++) {
48	                sb.append(String.format("%02X", hash[i]));
49	            }
50	            return sb.toString();
51	        }
52	        catch (NoSuchAlgorithmException e) {
53	            throw new IllegalStateException("SHA-256 not available", e);
54	        }
55	    }
56	
57	    /** Last-name key: lower-cased, trimmed, with internal whitespace runs collapsed to one space. */
58	    private static String normalize(String value) {
59	        if (value == null) {
60	            return null;
61	        }
62	        String collapsed = value.trim().replaceAll("\\s+", " ");
63	        return collapsed.isEmpty() ? null : collapsed.toLowerCase(Locale.ROOT);
64	    }
65	}
