1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
7	
8	/**
9	 * The single duplicate check, run before {@link SaveOwner}. Duplicate detection is
10	 * expressed entirely through the {@code identityKey} (see {@link OwnerIdentity}): a new
11	 * owner is rejected as a 409 Conflict only when its whole {@code identityKey} equals an
12	 * existing owner's — an identical owner is a hard duplicate. There is no separate
13	 * household-duplicate block; the computed {@code householdId} no longer feeds duplicate
14	 * detection.
15	 *
16	 * <p>Because the telephone is part of that key, two owners with the same last name and
17	 * postcode but different telephones (or emails) have different keys and are <em>both
18	 * allowed</em>: they are admitted and instead flagged a soft possible duplicate (see
19	 * {@link AssignOwnerPossibleDuplicate}). Only an exact identity match is a conflict.
20	 *
21	 * <p>Soft-deleted owners (flagged {@code deleted}) are skipped entirely: they no longer
22	 * block a create, so a normally-blocking duplicate is admitted when the only matching
23	 * owner has been deleted.
24	 */
25	public class RejectDuplicateOwnerIdentity {
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
28	            throws DuplicateOwnerIdentityException {
29	        String identityKey = OwnerIdentity.identityKey(owner);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
32	                continue; // never conflict with the owner itself
33	            }
34	            if (existing.isDeleted()) {
35	                continue; // a soft-deleted owner no longer blocks a create
36	            }
37	            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
38	                throw new DuplicateOwnerIdentityException(
39	                        "An owner with the same identity already exists");
40	            }
41	        }
42	    }
43	}
